<script>
import { Component, Prop, Vue } from "vue-property-decorator";
import Loading from "../../loading/loading";

const wait = (amount = 0) => {
  return new Promise((resolve) => setTimeout(resolve, amount));
};

@Component({
  components: {
    Loading,
  },
})
export default class DElementLibraryExampleAsyncPageContent extends Vue {
  @Prop({
    type: Function,
  })
  goTo;

  @Prop({
    type: Function,
  })
  goBack;

  @Prop({
    type: Function,
  })
  goHome;

  isLoading = false;

  // Load for 3 seconds on mount
  async mounted() {
    this.isLoading = true;
    await wait(2000);
    this.isLoading = false;
  }
}
</script>

<template>
  <div>
    <div v-if="isLoading">
      <Loading :loading="isLoading" :size="48" />
    </div>
    <div v-else>
      <h1>Loaded!</h1>
      <button @click="goHome">Home</button>
    </div>
  </div>
</template>
